import json
import subprocess
import sys
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import List, Dict, Any

def validate_config(config: Dict[str, Any]) -> None:
    if not isinstance(config.get("max_parallel"), int) or config["max_parallel"] < 1:
        raise ValueError("max_parallel must be an integer >= 1")
    if not isinstance(config.get("min_start_interval"), (int, float)) or config["min_start_interval"] < 0:
        raise ValueError("min_start_interval must be a number >= 0")
    if not isinstance(config.get("row_template"), str) or not isinstance(config.get("page_template"), str):
        raise ValueError("row_template and page_template must be strings")
    if not isinstance(config.get("commands"), list):
        raise ValueError("commands must be a list")

def run_command_with_throttle(cmd: Dict[str, str], max_parallel: int, min_start_interval: float) -> Dict[str, Any]:
    start_time = time.time()
    result = {"name": cmd["name"], "cmd": cmd["cmd"]}
    with ThreadPoolExecutor(max_workers=1) as executor:
        future = executor.submit(subprocess.run, cmd["cmd"], shell=True, capture_output=True, text=True)
        result["output"] = future.stdout + future.stderr
        result["exit_code"] = future.returncode
    result["duration"] = round(time.time() - start_time, 3)
    return result

def process_commands_with_throttle(commands: List[Dict[str, str]], max_parallel: int, min_start_interval: float) -> List[Dict[str, Any]]:
    results = []
    command_times = []
    with ThreadPoolExecutor(max_parallel=max_parallel) as executor:
        futures = []
        for cmd in commands:
            future = executor.submit(run_command_with_throttle, cmd, max_parallel, min_start_interval)
            futures.append(future)
        for future in as_completed(futures):
            result = future.result()
            results.append(result)
            command_times.append(time.time())
    return results

def render_row_template(row_data: Dict[str, Any], row_template: str) -> str:
    return row_template.replace("{{name}}", str(row_data["name"])).replace("{{status}}", "ok" if row_data["exit_code"] == 0 else "failed").replace("{{duration}}", str(row_data["duration"])).replace("{{output}}", str(row_data["output"]))

def generate_html(config: Dict[str, Any], results: List[Dict[str, Any]]) -> str:
    rows = []
    for result in results:
        rendered_row = render_row_template(result, config["row_template"])
        rows.append(rendered_row)
    rows_html = "\n".join(rows)
    return config["page_template"].replace("{{rows}}", rows_html)

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    with open(sys.argv[1], "r") as f:
        config = json.load(f)

    validate_config(config)

    results = process_commands_with_throttle(config["commands"], config["max_parallel"], config["min_start_interval"])

    with open(sys.argv[2], "w", encoding="utf-8") as f:
        f.write(generate_html(config, results))

if __name__ == "__main__":
    main()
